import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Web Frontend — Interfaces That Feel Instant","description":"React, Vue, Next.js, Tailwind, state management and accessibility — building fast, modern web interfaces.","frontmatter":{"title":"Web Frontend — Interfaces That Feel Instant","description":"React, Vue, Next.js, Tailwind, state management and accessibility — building fast, modern web interfaces."},"headers":[],"relativePath":"en/skills/web/index.md","filePath":"en/skills/web/index.md"}`),a={name:`en/skills/web/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="web-frontend-—-interfaces-that-feel-instant" tabindex="-1">Web Frontend — Interfaces That Feel Instant <a class="header-anchor" href="#web-frontend-—-interfaces-that-feel-instant" aria-label="Permalink to “Web Frontend — Interfaces That Feel Instant”">​</a></h1><p>The frontend is where users judge everything they will never see. I build interfaces that load fast, degrade gracefully and feel immediate — because a beautiful backend behind a janky UI is a tree falling in an empty forest.</p><h2 id="the-toolbox" tabindex="-1">The toolbox <a class="header-anchor" href="#the-toolbox" aria-label="Permalink to “The toolbox”">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>Tools</th></tr></thead><tbody><tr><td>Frameworks</td><td>React, Vue, Angular, Next.js, Nuxt</td></tr><tr><td>Styling</td><td>Tailwind CSS, CSS architecture, design tokens, responsive systems</td></tr><tr><td>State</td><td>Pinia, Zustand, Redux Toolkit, query caches</td></tr><tr><td>Mobile &amp; Desktop</td><td>React Native, Expo, Flutter, Ionic, Electron, Tauri</td></tr><tr><td>Performance</td><td>Code splitting, image budgets, Core Web Vitals</td></tr></tbody></table><p>This very site is a working demonstration: a cloned VitePress theme adapted to two locales with a custom SVG icon system and generated illustration set. My admin panels for <a href="/Usf/en/projects/usf-panel/">Usf Panel</a> follow the same rules under far tighter constraints: single-file backends with polished, responsive frontends.</p><div class="tip custom-block"><p class="custom-block-title">Responsive is a feature</p><p>Most of my visitors arrive on a phone over a slow network. Treating responsiveness and payload size as afterthoughts is shipping a broken product — so I design for both from the first commit.</p></div>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};